    int n, m;
    cin >> n >> m;
    vector<vector<int>> grid(n, vector<int>(m));
    for (auto &row : grid)
        for (int &x : row) cin >> x;
    int sr, sc, color;
    cin >> sr >> sc >> color;
    Solution s;
    vector<vector<int>> ans = s.floodFill(grid, sr, sc, color);
    for (auto &row : ans) {
        for (int x : row) cout << x << " ";
        cout << endl;
    }
}

